// Normalize multiple backslashes to a single backslash
function normalizeBackslashes(text) {
  if (!text) return text;
  return text.replace(/\\+/g, '\\');
}

// Shorten sequences of 3 or more dashes to just 2 dashes
function shortenDashes(text) {
  if (!text) return text;
  return text.replace(/-{3,}/g, '--');
}

// Escape Telegram MarkdownV2 special characters except inside URLs
// Escape Telegram MarkdownV2 special characters except pipes and backslashes
function escapeMarkdown(text) {
  if (!text) return text;
  return text
    // Note: We DO NOT escape backslash and pipe here to keep tables intact
    .replace(/_/g, '\\_')     // underscore
    .replace(/\*/g, '\\*')    // asterisk
    .replace(/\[/g, '\\[')    // open bracket
    .replace(/\]/g, '\\]')    // close bracket
    .replace(/\(/g, '\\(')    // open parenthesis
    .replace(/\)/g, '\\)')    // close parenthesis
    .replace(/~/g, '\\~')     // tilde
    .replace(/`/g, '\\`')     // backtick
    .replace(/>/g, '\\>')     // greater than
    .replace(/#/g, '\\#')     // hash
    .replace(/\+/g, '\\+')    // plus
    .replace(/=/g, '\\=')     // equal
    // .replace(/\|/g, '\\|') // **Do NOT escape pipes**
    .replace(/\{/g, '\\{')    // open curly brace
    .replace(/\}/g, '\\}')    // close curly brace
    .replace(/!/g, '\\!');    // exclamation
}


// Clean URLs by removing backslashes to avoid invalid markdown links
function cleanUrl(url) {
  if (!url) return url;
  return url.replace(/\\/g, '');
}

// Compose the final Telegram message with bold titles and clickable links
function formatMessage(aiContent, searchResults) {
  if (!aiContent) return '';

  // Normalize backslashes and shorten dashes only in aiContent
  let text = normalizeBackslashes(aiContent);
  text = shortenDashes(text);

  // Escape markdown for main content only
  text = escapeMarkdown(text) + '\n\n';

  // Append search results without over-escaping URLs and markdown syntax
  searchResults.forEach((result, i) => {
    // Escape title and snippet only
    const title = escapeMarkdown(result.title);
    const snippet = escapeMarkdown(result.snippet);
    // Clean url without escaping markdown syntax
    const url = cleanUrl(result.url);

    // Format with markdown - title bold, url as clickable link
    text += `${i + 1}. *${title}*\n[${url}](${url})\n${snippet}\n\n`;
  });

  return text;
}

// Your JSON input
const aiContent = $json.choices?.[0]?.message?.content || '';
const results = $json.search_results || [];

// Format the full message text, escaping properly
const finalMessage = formatMessage(aiContent, results);

// Telegram has max message length of 4096 chars; split by line to avoid breaking entities
function safeSplit(text, maxLength) {
  const parts = [];
  let currentPart = '';

  text.split('\n').forEach(line => {
    if ((currentPart + '\n' + line).length > maxLength) {
      parts.push(currentPart);
      currentPart = line;
    } else {
      currentPart += (currentPart.length ? '\n' : '') + line;
    }
  });

  if (currentPart.length) parts.push(currentPart);
  return parts;
}

const maxLength = 4096;
const parts = safeSplit(finalMessage, maxLength);

// Return array of messages formatted for Telegram API
return parts.map(part => ({
  json: {
    text: part,
    chat_id: $json.chat_id || $('Telegram Trigger').item.json.message.chat.id,
    parse_mode: 'MarkdownV2',
  },
}));
